verus! {
    // Finds the index of the first occurrence of the minimum element in a non‐empty vector of i8.
    pub fn argmin(a: Vec<i8>) -> (result: usize)
        requires a.len() > 0
        ensures  result < a.len()
        ensures  forall |i: usize| i < a.len() ==> a[result] <= a[i]
        ensures  forall |j: usize| j < result    ==> a[j] > a[result]
    {
        // idx = the current index of the smallest value seen so far
        let mut idx: usize = 0;
        // min_val = a[idx]
        let mut min_val: i8 = a[0];
        // we will scan from i = 1 up to a.len()
        let mut i: usize = 1;

        // Loop until we have inspected all positions
        while i < a.len()
            invariant 1 <= i && i <= a.len()
            invariant idx < i
            invariant min_val == a[idx]
            // up to but not including i, a[idx] is a global minimum
            invariant forall |k: usize| k < i ==> a[idx] <= a[k]
            // before idx, all values are strictly greater than a[idx]
            invariant forall |j: usize| j < idx ==> a[j] > a[idx]
            decreases a.len() - i
        {
            let ai = a[i];
            if ai < min_val {
                // we found a new smaller value, and its first occurrence at i
                min_val = ai;
                idx = i;
            }
            i = i + 1;
        }

        // by the loop invariants we have all the postconditions
        result = idx;
    }
}